--[[

----------- This file is generated by AI (DeepSeek) ----------

On-demand MCP filesystem roots for CodeCompanion.

Phase 1 - automatic: the `project` server (a deferred config, so it resolves to
whatever `getcwd()` is when the first chat opens) is listed in
`mcp.opts.default_servers`, so the current project root is always served.

Phase 2 - on demand: the `add_mcp_root` tool lets the LLM ask for another
directory. It always prompts you first (the tool is `protect`ed) and, once you
accept, it starts a new `@modelcontextprotocol/server-filesystem` for that
directory and attaches its tools to the *current* chat, so the LLM can use them
on its very next turn.

Why the run-time work rather than plain config: `mcp.servers` is read once per
server (deferred configs are memoized), and a server's tool group is only added
to a chat at creation time. Adding a second root therefore needs both
`config.mcp.servers[name] = ...` and `Chat.ToolRegistry:add`.
]]

local M = {}

-- Tools on `@modelcontextprotocol/server-filesystem` that mutate the disk.
-- Everything else it exposes only reads.
local MUTATING = {
    "write_file",
    "edit_file",
    "move_file",
    "create_directory",
    "append_file",
    "copy_file",
}

---Turn a path into a stable, valid MCP server name
---@param dir string
---@return string
local function slug(dir)
    local s = vim.fs.normalize(dir):gsub("[/\\]+$", ""):gsub("^/", "")
    s = s:gsub("[^%w]+", "_"):gsub("^_+", ""):gsub("_+$", "")
    if s == "" then
        s = "root"
    end
    return s:sub(1, 40)
end

---@param dir string
---@return string
function M.server_name(dir)
    return "fs_" .. slug(dir)
end

---Directories served this session, keyed by directory -> server name.
---Needed because the `project` server is a deferred config whose directory only
---exists once `getcwd()` is read.
---@type table<string, string>
local dynamic = {}

---The served directory of a server config, if it can be read statically
---@param cfg table|function
---@return string|nil
local function served_dir(cfg)
    if type(cfg) ~= "table" or type(cfg.cmd) ~= "table" or #cfg.cmd == 0 then
        return nil
    end
    local last = cfg.cmd[#cfg.cmd]
    if type(last) ~= "string" or not last:match("^[/~]") then
        return nil
    end
    return vim.fs.normalize(vim.fn.expand(last))
end

---Is this directory already served by a configured server?
---@param dir string
---@return boolean
---@return string|nil name The server already serving it
function M.served(dir)
    dir = vim.fs.normalize(vim.fn.expand(dir))
    dir = dir:gsub("[/\\]+$", "")

    for known, name in pairs(dynamic) do
        if known == dir then
            return true, name
        end
    end

    for name, cfg in pairs(require("codecompanion.config").mcp.servers) do
        local served = served_dir(cfg)
        if served and served:gsub("[/\\]+$", "") == dir then
            return true, name
        end
    end

    return false
end

---Always ask before a `server`'s write tools run.
---
---The approvals gate only knows about `protect`, and only reads the global
---`interactions.chat.tools` table, so a per-server `tool_defaults` alone would
---let writes through in Auto mode. Dynamic servers can't be anticipated in
---config, hence this runs once the server's tools are known.
---@param name string
function M.protect_writes(name)
    local cfg = require("codecompanion.config")
    local tools = require("codecompanion.mcp").get_registered_tools()

    for _, tool in ipairs(MUTATING) do
        local full = name .. "_" .. tool
        if tools[full] then
            cfg.interactions.chat.tools[full] = vim.tbl_deep_extend("force", cfg.interactions.chat.tools[full] or {}, {
                opts = { protect = true },
            })
        end
    end
end

---The `protect` shadows for a server, to be merged in before `setup()`.
---
---Listed statically so they exist from the very first chat, rather than only
---after the server reports its tools.
---@param name string
---@return table<string, table>
function M.shadows(name)
    local out = {}
    for _, tool in ipairs(MUTATING) do
        out[name .. "_" .. tool] = { opts = { protect = true } }
    end
    return out
end

---Add a server's tool group to an existing chat buffer
---@param chat CodeCompanion.Chat
---@param name string
---@param on_ready? fun()
---@return boolean
local function attach(chat, name, on_ready)
    local mcp = require("codecompanion.mcp")
    local done, reported = false, false

    local function add()
        if done then
            return
        end
        done = true
        M.protect_writes(name)
        -- `refresh` re-reads the tool config, picking up the group registered
        -- by the server plus the `protect` shadows above
        chat.tools:refresh({ adapter = chat.adapter })
        chat.tool_registry:add(mcp.tool_prefix() .. name, { config = chat.tools.tools_config })
        if on_ready and not reported then
            reported = true
            on_ready()
        end
    end

    local status = mcp.get_status()[name]
    if status and status.ready and status.tool_count > 0 then
        add()
        return true
    end

    local ok, err = mcp.enable_server(name, { on_tools_loaded = add })
    if not ok then
        return false, err
    end
    return true
end

M.attach = attach

---Register (but do not start) a filesystem server for `dir`
---@param dir string
---@return string|nil name
---@return string|nil error_message
function M.add_root(dir)
    dir = vim.fs.normalize(vim.fn.expand(dir))
    dir = dir:gsub("[/\\]+$", "")

    if vim.fn.isdirectory(dir) == 0 then
        return nil, string.format("`%s` is not a directory", dir)
    end

    local already, existing = M.served(dir)
    if already then
        return nil, string.format("`%s` is already served by the MCP server `%s`", dir, existing)
    end

    local name = M.server_name(dir)
    require("codecompanion.config").mcp.servers[name] = {
        cmd = { "npx", "-y", "@modelcontextprotocol/server-filesystem", dir },
        -- Paired with the `protect` shadows: `require_approval_before` is what
        -- makes the orchestrator pause at all
        tool_defaults = { require_approval_before = true },
    }

    dynamic[dir] = name
    return name
end

---Deferred config for the auto-served project root.
---
---Returned as a function so it reads `getcwd()` when the first chat needs it,
---and memoized by CodeCompanion so one `npx` process serves the whole session.
---@return table
function M.project_server()
    local root = vim.fs.normalize(vim.fn.getcwd()):gsub("[/\\]+$", "")
    dynamic[root] = "project"
    return {
        cmd = { "npx", "-y", "@modelcontextprotocol/server-filesystem", root },
        tool_defaults = { require_approval_before = true },
    }
end

---Start `name` on `chat`, calling `on_ready` once its tools are in the buffer
---@param chat CodeCompanion.Chat
---@param name string
---@param on_ready? fun()
---@return boolean
function M.start(chat, name, on_ready)
    return attach(chat, name, on_ready)
end

---Register `add_mcp_root` in the chat tools config, along with the `protect`
---shadows for every mutating tool of every configured MCP server.
---
---Must run before the first chat is created, because `Tools.new` snapshots the
---tool config and only refreshes on a model change or an explicit `refresh`.
function M.setup()
    local cfg = require("codecompanion.config")

    cfg.interactions.chat.tools["add_mcp_root"] = {
        description = "Serve one more directory with an MCP filesystem server",
        -- Resolved by the tool system on every call, so the table below can hold
        -- functions that close over the current chat
        callback = M.tool,
        ---@param opts { adapter: CodeCompanion.HTTPAdapter|CodeCompanion.ACPAdapter }
        ---@return boolean
        enabled = function(opts)
            -- ACP agents run their own tools and their own MCP clients
            return not (opts and opts.adapter and opts.adapter.type == "acp")
        end,
    }

    -- `protect` is per tool name, and the names are `<server>_<tool>`, so every
    -- server needs its shadows present up front. Without this the filter's
    -- post_filter (which drops tools whose server is stopped) still hides them.
    for name in pairs(cfg.mcp.servers) do
        cfg.interactions.chat.tools = vim.tbl_deep_extend("force", cfg.interactions.chat.tools, M.shadows(name))
    end
end

--------------------------------------------------------------------------------
-- The `add_mcp_root` tool
--------------------------------------------------------------------------------

---@return table
function M.tool()
    return {
        name = "add_mcp_root",
        kind = "other",
        -- Always ask, even in Auto mode
        opts = { require_approval_before = true },
        system_prompt = table.concat({
            "You can only read and write the directories already served by an MCP filesystem server.",
            "`add_mcp_root` opens one more directory for the rest of the session. It asks the user,",
            "so call it only when a task genuinely needs a path outside those directories, and pass",
            "a real directory path - never the repository root when it is already served.",
        }, " "),
        schema = {
            type = "function",
            ["function"] = {
                name = "add_mcp_root",
                description = table.concat({
                    "Serve one more directory with an MCP filesystem server so its files become readable.",
                    "Use this when the user asks about a path outside the directories you can already reach.",
                    "The user must approve it, and the new tools appear on your next turn.",
                }, " "),
                parameters = {
                    type = "object",
                    properties = {
                        directory = {
                            type = "string",
                            description = "Absolute path of the directory to serve",
                        },
                        reason = {
                            type = "string",
                            description = "Why this directory is needed, shown to the user",
                        },
                    },
                    required = { "directory", "reason" },
                },
            },
        },
        cmds = {
            ---@param self CodeCompanion.Tools.Tool
            ---@param args { directory: string, reason: string }
            ---@param input { output_cb: fun(msg: { status: string, data: string }) }
            function(self, args, input)
                local chat = self.chat
                local dir = vim.fs.normalize(vim.fn.expand(args.directory))

                local name, err = M.add_root(dir)
                if not name then
                    return input.output_cb({ status = "success", data = err })
                end

                local finished = false
                local function finish(status, data)
                    if finished then
                        return
                    end
                    finished = true
                    input.output_cb({ status = status, data = data })
                end

                -- `on_tools_loaded` fires when the server has answered
                -- `initialize` and listed its tools, i.e. when the new schemas
                -- are safe to use on the next turn
                local ok = attach(chat, name, function()
                    local count = require("codecompanion.mcp").get_tool_count(name)
                    finish(
                        "success",
                        string.format(
                            "`%s` is now served by the MCP server `%s` (%d tools, added to this chat). "
                                .. "Files under it are readable and writable now, subject to approval.",
                            dir,
                            name,
                            count
                        )
                    )
                end)

                if not ok then
                    return finish("error", string.format("Could not start an MCP server for `%s`", dir))
                end

                -- `npx` may need to download the server on first use
                vim.defer_fn(function()
                    finish(
                        "error",
                        string.format(
                            "Started `%s` for `%s` but it did not report any tools within %d s. "
                                .. "Check `npx` connectivity, or run `:lua=vim.print(require('codecompanion.mcp').get_status())`.",
                            name,
                            dir,
                            60
                        )
                    )
                end, 60000)
            end,
        },
        output = {
            ---@param self CodeCompanion.Tools.Tool
            ---@return string
            prompt = function(self)
                local args = self.args or {}
                return string.format(
                    "Serve `%s` with a new MCP filesystem server?\n\n**Reason**: %s",
                    args.directory or "?",
                    args.reason or "_(none given)_"
                )
            end,

            ---@param self CodeCompanion.Tools.Tool
            ---@param stdout table
            ---@param meta { tools: CodeCompanion.Tools }
            success = function(self, stdout, meta)
                local content = vim.iter(stdout):flatten():join("\n")
                meta.tools.chat:add_tool_output(self, { content = content })
            end,

            ---@param self CodeCompanion.Tools.Tool
            ---@param stderr table
            ---@param meta { tools: CodeCompanion.Tools }
            error = function(self, stderr, meta)
                local content = vim.iter(stderr):flatten():join("\n")
                meta.tools.chat:add_tool_output(self, { content = "add_mcp_root failed: " .. content })
            end,
        },
    }
end

--------------------------------------------------------------------------------
-- Manual entry point
--------------------------------------------------------------------------------

---Prompt for a directory and serve it on the current chat
---@param chat CodeCompanion.Chat
function M.prompt(chat)
    vim.ui.input({ prompt = "Directory to serve: ", completion = "dir", default = vim.fn.getcwd() .. "/" }, function(dir)
        if not dir or dir == "" then
            return
        end

        local name, err = M.add_root(dir)
        if not name then
            return vim.notify(err, vim.log.levels.WARN, { title = "CodeCompanion MCP" })
        end

        M.start(chat, name, function()
            vim.notify(
                string.format("MCP server `%s` started for `%s`", name, vim.fs.normalize(vim.fn.expand(dir))),
                vim.log.levels.INFO,
                { title = "CodeCompanion MCP" }
            )
        end)
    end)
end

return M
